using System;
int Total(int price, int quantity) {
    if (price < 0 || quantity < 0) throw new ArgumentOutOfRangeException();
    return checked(price * quantity);
}
Console.WriteLine(Total(12, 3));
Console.WriteLine(Total(12, 0));
try { Total(12, -1); }
catch (ArgumentOutOfRangeException) { Console.WriteLine("Invalid input rejected"); }

